"""Generate registry/ColorSchemes.xcu (Tools > Options > Application Colors) from the tokens."""
import argparse
from pathlib import Path
from xml.sax.saxutils import quoteattr

from tokens import load_tokens, lo_color

HEADER = """<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by tools/build_registry.py from design/tokens.json. Do not edit. -->
<oor:component-data xmlns:oor="http://openoffice.org/2001/registry"
                    xmlns:xs="http://www.w3.org/2001/XMLSchema"
                    oor:name="UI" oor:package="org.openoffice.Office">
  <node oor:name="ColorScheme">
    <node oor:name="ColorSchemes">
"""
FOOTER = """    </node>
  </node>
</oor:component-data>
"""


def entry(name, value):
    visible, color = value if isinstance(value, list) else (None, value)
    lines = [f'        <node oor:name="{name}">']
    if visible is not None:
        lines.append(f'          <prop oor:name="IsVisible"><value>{str(visible).lower()}</value></prop>')
    lines.append(f'          <prop oor:name="Color"><value>{lo_color(color)}</value></prop>')
    lines.append("        </node>")
    return "\n".join(lines)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", required=True)
    args = ap.parse_args()

    parts = [HEADER]
    schemes = load_tokens()["colorSchemes"]
    for scheme, entries in schemes.items():
        if "$extends" in entries:
            entries = {**schemes[entries["$extends"]], **entries}
        entries = {k: v for k, v in entries.items() if not k.startswith("$")}
        parts.append(f'      <node oor:name={quoteattr(scheme)} oor:op="replace">\n')
        parts.append("\n".join(entry(k, v) for k, v in entries.items()) + "\n")
        parts.append("      </node>\n")
    parts.append(FOOTER)
    out = Path(args.out)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text("".join(parts), encoding="utf-8")
    print(f"color schemes -> {out}")


if __name__ == "__main__":
    main()
